import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
import { VERSION_SOURCE, versionFromLiteral, compareVersions, versionsEqual, nextVersion } from '../../../../../engine/version.mjs';

// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
// engine tree vendors wholesale on every converge; a pack's directory ships only
// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`
// (updates/pack-update.mjs). So a canon commit that edits `packs/<id>/` without
// touching that number lands here, goes green here, and reaches no member — the
// fleet keeps the old bytes while canon believes the change shipped.
//
// #939 is what that costs. A check vocabulary rename updated the engine and the
// canon's own packs in one commit: the engine, delivered unconditionally, reached
// every member and rejected the old spelling; the pack carrying the new spelling
// stayed at `version: 1` and reached nobody. The mixed tree failed each member's
// self-test, the update PR parked, and the fix could not arrive by the route that
// delivers fixes. Seven repos sat frozen for five days.
//
// So the invariant this rule holds is one line: A CHANGE UNDER `packs/<id>/` IS A
// CHANGE TO THAT PACK'S VERSION. Every SHIPPING byte counts, because every one of
// them rides the same directory copy — prose, a skill, a check module, a migration
// record. A pack's tests sit beside the files they cover and are the one thing in
// that directory no vendor set carries (compute-vendor-set drops `*.test.mjs`), so
// nobody is waiting on them and a bump for one would re-deliver every pack in the
// tree to say nothing.
// It is the pack-side twin of `engine-release-record` (the claudinite local pack),
// which holds the same line for `ENGINE_VERSION`.
//
// WORK SCOPE: the question is what THIS change did. The tree always contains a
// version number; only the diff says whether it moved with the content beside it.
const LOCAL_PACKS = '.claudinite/local/packs';

// Each pack's version-bump log, next to its manifest — see `versionRecorded`
// below for what it must carry once a bump lands.
export const VERSIONS_FILENAME = 'VERSIONS.md';

// The pack ids a changed-file list touches, in first-seen order. Anchored at
// `packs/<id>/` so the canon's own local packs (which vendor nowhere, carry no
// version and reach no member) and the tree's own files (`packs/README.md`,
// `packs/directory.GENERATED.md`) are outside it by construction. Tests drop out for
// the same reason the local packs do: nothing delivers them. `VERSIONS.md` drops
// out too — it is the log OF bumps, not content a bump ships, so editing it alone
// (recording a bump made elsewhere in the same change, or a wording fix to an old
// row) must never itself demand another bump.
export function packsTouched(changed) {
  const ids = [];
  for (const file of changed ?? []) {
    if (file.startsWith(`${LOCAL_PACKS}/`) || file.endsWith('.test.mjs') || file.endsWith(`/${VERSIONS_FILENAME}`)) continue;
    const m = /^packs\/([^/]+)\//.exec(file);
    if (m && !ids.includes(m[1])) ids.push(m[1]);
  }
  return ids;
}

// The `version:` a pack manifest declares, or null when it declares none (a
// manifest that is absent on one side of the diff, or one the schema check owns).
// The preceding-character class is what keeps `minEngineVersion:` out of it.
const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[\s{,])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
export function declaredPackVersion(text) {
  const m = PACK_VERSION_RE.exec(text ?? '');
  return m ? versionFromLiteral(m[1]) : null;
}

// A row of the pack's VERSIONS.md is a table row
// whose first cell is the bare version — the same shape `engine/RELEASES.md`
// rows use, so the log reads as a table a human maintains, not a format this
// check invented. No run link is required here (unlike an engine release): a
// pack bump has no canary rehearsal to cite, so the row's own prose is the
// record.
const ROW_VERSION_RE = new RegExp(String.raw`^\|\s*(${VERSION_SOURCE})\s*\|`);

// Every version a log's rows claim, each with the 1-based line it sits on. The
// world-scope `pack-version-claimed-once` reads the same rows to ask whether any
// number is claimed twice, so the shape of a row is defined here once.
export function rowVersions(text) {
  const claims = [];
  (text ?? '').split('\n').forEach((line, i) => {
    const m = ROW_VERSION_RE.exec(line.trim());
    if (m) claims.push({ version: versionFromLiteral(m[1]), line: i + 1 });
  });
  return claims;
}

export function versionRecorded(text, version) {
  return rowVersions(text).some((claim) => versionsEqual(claim.version, version));
}

const rule = {
  id: 'pack-version-bumped',
  severity: 'blocking',
  scope: 'work',
  description: 'A change under packs/<id>/ bumps that pack\'s version, and a bump lands with its VERSIONS.md row',
  doc: 'docs/versioned-updates/DESIGN.md',
  why: 'a member receives a pack directory only when the canon\'s version exceeds the one it has installed, so content edited without a bump reaches nobody while canon CI reports it shipped (#939 froze seven repos for five days that way); an unrecorded bump is the same evidence gap on a smaller scale — "what did version N change?" becomes unanswerable once the commit scrolls out of history',

  run(work) {
    const findings = [];
    for (const id of packsTouched(work.changedFiles)) {
      const manifest = `packs/${id}/pack.mjs`;
      const head = declaredPackVersion(work.read(manifest));
      if (head === null) continue;                     // the pack was deleted, or declares no version — other rules own that
      const base = declaredPackVersion(work.readBase(manifest));
      if (base === null) continue;                     // a pack this change introduces: its first version ships to everyone
      const moved = compareVersions(head, base);

      if (moved <= 0) {
        findings.push(finding(rule, {
          file: manifest,
          what: moved === 0
            ? `this change edits packs/${id}/ but leaves its version at ${head}`
            : `packs/${id}/ moves its version backwards, ${base} → ${head}`,
          fix: moved === 0
            ? `raise \`version\` in ${manifest} to '${nextVersion(base)}' — the version is the whole delivery signal, so an edit `
              + 'that does not move it stays in the canon forever'
            : 'pack versions only ever increase — the update flow reads them as an ordering, so a lowered number tells '
              + 'every member it is already up to date',
        }));
        continue;
      }

      const versionsFile = `packs/${id}/${VERSIONS_FILENAME}`;
      if (!versionRecorded(work.read(versionsFile), head)) {
        findings.push(finding(rule, {
          file: versionsFile,
          what: `packs/${id}/ bumps its version to ${head}, and ${versionsFile} carries no row for it`,
          fix: `add a row to ${versionsFile} for version ${head} saying what changed`,
        }));
      }
    }
    return findings;
  },
};

export default rule;

// THE ENGINE VERSION — the value that says which engine release a repo is running
// (docs/versioned-updates/DESIGN.md §2). The engine root vendors wholesale, so this
// module ships into every mount with the rest of the engine, and a member's stamp
// records the value it received (vendoring/apply-vendor-set.mjs). That pair is what
// makes "installed version → target version" answerable on the member side: which
// engine migrations still apply, and whether a pack's minimum is satisfied.
//
// DATE-ANCHORED, `<day>.<n>` — the shape, the ordering and why the corpus versions
// this way rather than in semver are stated below the constant. Every comparison made
// of this value is "installed < target" over a total order, so the format buys one
// thing over the plain counter it replaced: the version says when it was cut, without
// a second lookup.
//
// ADVANCED BY RELEASE, never by an ordinary change: a release is a snapshot that has
// passed the live canary rehearsal once (DESIGN §2.1), and the bump is what declares
// that happened. An engine migration is written against the version it lands in — it
// applies to repos below that value.
export const ENGINE_VERSION = '60823.1';

// THE VERSION FORMAT — how every engine and pack version in the corpus is written,
// read and ordered. The helpers below are imported by every side that creates a
// version (each `packs/*/pack.mjs`), stamps one (updates/), compares two (the update
// planners, the dashboard, the fleet roster) or scrapes one out of source text over
// the API. They live beside the constant rather than in a module of their own so the
// engine surface a member's mount must carry for any of it is one file.
//
// THE SHAPE IS `<day>.<n>` — `60820.1`, displayed with a leading `v`. The day part
// is `(year - 2020) * 10000 + month * 100 + day`, so 2026-08-20 is 60820; the second
// part is the running number of versions cut on that day, starting at 1. It is a
// STRING and never a float: `60820.10` and `60820.1` are different versions and the
// same number.
//
// Anchoring the year on 2020 rather than taking its last digit is what keeps the day
// part monotonic past 2029 — 2030 reads 100101, above every 2029 value, where a
// last-digit year would wrap to 0 and sort a decade of releases underneath.
//
// WHY DATE-ANCHORED AT ALL. Every comparison the update flows make is still
// "installed < target" over a total order — nothing here needs semver's three
// components. What the plain counter could not do is say WHEN: a member stamped at 6
// against a canon at 13 is behind by an unknown amount of time, and the fleet
// surfaces that as a number a reader has to go and date by hand.
//
// LEGACY TOLERANCE, until 2026-08-27 (#1106). Versions were plain positive integers
// until 2026-08-20, and the integers are still sitting in every member's stamp, in
// each pack's `minEngineVersion` floor and in every migration record's range. So a
// legacy integer parses here as `<n>.0` — below every date-anchored version, which
// is exactly where a member that has not re-stamped belongs. Dependency-free, like
// the manifest spec it serves.

// The day part of a Date, in UTC. Callers that have a `YYYY-MM-DD` string already
// (the corpus passes `today` around in that form) can hand it straight over.
export function versionDay(when = new Date()) {
  const d = typeof when === 'string' ? new Date(`${when.slice(0, 10)}T00:00:00Z`) : when;
  if (Number.isNaN(d.getTime())) return null;
  return (d.getUTCFullYear() - 2020) * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate();
}

// A date-anchored version, as its two parts. The day part is at least five digits
// (2020-01-01 is 101, but nothing predates the scheme, and the smallest day a repo
// can carry is 60820), which is what keeps it unambiguously apart from a legacy
// counter — those never reached three figures.
const DATE_ANCHORED = /^([1-9]\d{4,5})\.([1-9]\d*)$/;

// A version in EITHER form, as `{ day, seq }`, or null when the value is not one.
// A legacy integer is `{ day: n, seq: 0 }` — the same tuple shape, so every
// comparison below is written once and knows nothing about the two spellings.
//
// ZERO IS READABLE and is not an absence: an install runs from version zero
// (docs/versioned-updates/DESIGN.md §3), so a stamp may hold one and it must sort
// below everything rather than read as "this stamp says nothing". Nothing may
// DECLARE it — that is `isDeclaredVersion` below.
export function parseVersion(v) {
  if (typeof v === 'number') return Number.isInteger(v) && v >= 0 ? { day: v, seq: 0 } : null;
  if (typeof v !== 'string') return null;
  const m = DATE_ANCHORED.exec(v.trim());
  return m ? { day: Number(m[1]), seq: Number(m[2]) } : null;
}

export const isVersion = (v) => parseVersion(v) !== null;

// What a manifest or a release may WRITE: a real version, never the install floor.
export const isDeclaredVersion = (v) => isVersion(v) && v !== 0;

// True for the retiring spelling only — the one thing the removal change (#1106)
// greps for, and what a reader needing to say "this predates the scheme" asks.
export const isLegacyVersion = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0;

// Order two versions: negative when `a` is older. An UNPARSEABLE version is not an
// error and not a zero — it sorts as equal to everything, so a caller that cannot
// price one side reports "no gap" rather than inventing one in either direction.
// Callers that must distinguish absence from equality check `isVersion` first.
export function compareVersions(a, b) {
  const x = parseVersion(a);
  const y = parseVersion(b);
  if (!x || !y) return 0;
  return x.day - y.day || x.seq - y.seq;
}

export const versionAbove = (a, b) => compareVersions(a, b) > 0;

// Equality has to ask more than `compareVersions(a, b) === 0`: an unpriceable side
// compares equal to everything, so the two versions must both be real ones first.
export const versionsEqual = (a, b) => isVersion(a) && isVersion(b) && compareVersions(a, b) === 0;

export const formatVersion = ({ day, seq }) => `${day}.${seq}`;

// The next version to cut today, given the one that stands. A new day restarts the
// running number at 1; a second version on the same day is `.2`. A `current` that is
// legacy, absent or unparseable simply does not constrain today's number — the day
// part is already above every integer the old scheme ever reached.
export function nextVersion(current, today = new Date()) {
  const day = versionDay(today);
  const held = parseVersion(current);
  return held && held.day === day ? `${day}.${held.seq + 1}` : `${day}.1`;
}

// The version-shaped fragment for the text scrapers — the readers that lift a
// version out of `engine/version.mjs` or a `pack.mjs` fetched over the API, where
// there is nothing to import. Kept here so the six of them cannot disagree about
// what a version looks like; each wraps it in its own anchor.
export const VERSION_SOURCE = String.raw`\d+(?:\.\d+)?`;

// What such a scraper should hand back: the literal as it was written, so a legacy
// integer stays a number and a date-anchored version stays a string, and every
// comparison downstream is the same one function.
export function versionFromLiteral(text) {
  if (text == null) return null;
  const t = String(text).trim();
  const v = t.includes('.') ? t : Number(t);
  return isVersion(v) ? v : null;
}

import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
import { parseVersion, formatVersion } from '../../../../../engine/version.mjs';
import { VERSIONS_FILENAME, rowVersions } from '../workRules/pack-version-bumped.mjs';

// A PACK VERSION IS AN IDENTITY, NOT A COUNTER. `planPackUpdates` re-fetches a
// pack directory only where `installed < canon`, so the number is the fleet's
// whole name for a set of bytes. Two changes landing under one number means the
// members that converged between the two merges hold the first one's tree
// stamped with a number the second one also claims — and no converge will ever
// correct them, because their stamp already reads as current.
//
// That is not a hypothetical, and it is not an authoring mistake `pack-version-bumped`
// could have caught. Two branches cut from the same main both bump to the same
// next version, both record their row, both go green — each answered "did THIS
// change move the version" correctly and yes — and `pack.mjs` then AUTO-MERGES,
// because the two sides wrote identical bytes. Git has nothing to flag. #1482 is
// what it cost: #1466's janitor rule widening reached no member, the fleet swept
// with the old code, and the members' stamps read exactly as they should.
//
// THE ENGINE HAS NO TWIN OF THIS. `engine-release-record` (the claudinite local
// pack) is `pack-version-bumped`'s sibling, but the engine tree vendors WHOLESALE
// on every converge — its version records what landed, it does not gate what
// ships — so two releases sharing a number strand no content and there is nothing
// here to widen onto `engine/RELEASES.md`.
//
// THE DELIVERY half of that is `ci-work-scope.mjs` judging a push onto main
// against what the branch held before it, which re-asks `pack-version-bumped`
// where both branches are visible and so catches the collision as it lands.
// This is the RECORD half, and it is not the same
// question: a collision that landed before that gate existed left no red run
// behind, only two rows, and "what did version N change?" has two answers for
// as long as they both stand.
//
// WORLD SCOPE, because two rows claiming one number is a property of the tree,
// not of any diff — neither branch wrote both. `pack-version-bumped` forces a
// row for every bump, so a collision always leaves one.
const rule = {
  id: 'pack-version-claimed-once',
  severity: 'blocking',
  description: "No two rows of a pack's VERSIONS.md claim the same version",
  doc: 'docs/versioned-updates/DESIGN.md',
  why: 'a member re-fetches a pack only when canon\'s version exceeds its installed one, so two changes sharing a number leave whichever members converged between the two merges holding the first tree stamped with the second\'s number — permanently, with nothing red to say so (#1482)',

  run(ctx) {
    const findings = [];
    const logs = ctx.files.filter((f) => f.startsWith('packs/')
      && f.endsWith(`/${VERSIONS_FILENAME}`) && f.split('/').length === 3);
    for (const file of logs) {
      const seen = new Map();
      for (const { version, line } of rowVersions(ctx.read(file))) {
        const parsed = parseVersion(version);
        if (!parsed) continue;                    // not a version at all — the row shape is another rule's question
        const key = formatVersion(parsed);
        if (!seen.has(key)) { seen.set(key, line); continue; }
        findings.push(finding(rule, {
          file,
          line,
          what: `version ${version} is claimed by two rows (also line ${seen.get(key)}), so two changes shipped under one number`,
          fix: `fold the two rows into one saying what version ${version} carries — the members that took it between the two merges `
            + `hold one of them and will never be sent the other — and bump the pack to a fresh version, with its own row, to `
            + `re-deliver the content that was stranded`,
        }));
      }
    }
    return findings;
  },
};

export default rule;

