import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import rule from '../worldRules/pack-version-claimed-once.mjs';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '../../../../..');

// The world context a world rule receives — only the two members this rule reads.
const ctx = (files) => ({ files: Object.keys(files), read: (f) => files[f] ?? null });
const log = (...rows) => `# Version history\n\n| Version | Date | What changed |\n|---|---|---|\n`
  + rows.map(([v, what]) => `| ${v} | 2026-08-30 | ${what} |\n`).join('');

test('a log claiming each version once is clean', () => {
  assert.deepEqual(rule.run(ctx({
    'packs/demo/VERSIONS.md': log(['60830.2', 'Second.'], ['60830.1', 'First.']),
  })), []);
});

test('two rows claiming one version is the collision — one number, two trees', () => {
  const findings = rule.run(ctx({
    'packs/demo/VERSIONS.md': log(['60830.1', 'One branch.'], ['60830.1', 'The other branch.']),
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].file, 'packs/demo/VERSIONS.md');
  assert.equal(findings[0].line, 6);                    // the second claim, with the first named in the message
  assert.match(findings[0].what, /60830\.1 is claimed by two rows \(also line 5\)/);
});

test('each pack is asked on its own — one pack\'s version says nothing about another\'s', () => {
  assert.deepEqual(rule.run(ctx({
    'packs/demo/VERSIONS.md': log(['60830.1', 'Demo.']),
    'packs/other/VERSIONS.md': log(['60830.1', 'Other.']),
  })), []);
});

test('a log deeper than a pack root is not a pack\'s log', () => {
  assert.deepEqual(rule.run(ctx({
    'packs/demo/skills/x/VERSIONS.md': log(['60830.1', 'One.'], ['60830.1', 'Two.']),
  })), []);
});

test('a row whose first cell is not a version is another rule\'s question', () => {
  assert.deepEqual(rule.run(ctx({
    'packs/demo/VERSIONS.md': '| 60830.0 | — | Not a version. |\n| 60830.0 | — | Nor this. |\n',
  })), []);
});

// The tree's own logs, not a fixture: a check that has never met the real corpus
// proves only that its matching agrees with the shape the fixture spells.
test('the canon\'s own packs claim every version exactly once', () => {
  const tracked = execFileSync('git', ['ls-files', 'packs/*/VERSIONS.md'], { cwd: REPO, encoding: 'utf8' })
    .split('\n').filter(Boolean);
  assert.ok(tracked.length > 20, `expected the canon's packs to carry version logs, found ${tracked.length}`);
  const files = Object.fromEntries(tracked.map((f) => [f, readFileSync(join(REPO, f), 'utf8')]));
  assert.deepEqual(rule.run(ctx(files)).map((f) => `${f.file}: ${f.what}`), []);
});

// Claudinite's own curation pack — the fleet-facing work only Claudinite runs:
// promoting members' lessons into the shared canon (the growth lifecycle's
// central stage), sweeping the fleet's stacks for technologies the canon does
// not yet home, and policing the corpus's packs/ tree.
// (Prose-to-checks is no longer canon-only: it moved to claudinite-growth as a
// per-repo task with a `pack_paths` config — the canon runs it over its own packs/
// + local packs like any repo, per the per-project-scheduling redesign.)
//
// A LOCAL pack (.claudinite/local/packs/), by owner decision (2026-07-19): the
// canon home's curation duties are project-specific content — Claudinite
// maintaining Claudinite — so they live on the home's own capture surface, not
// in the portable packs/ canon. Its tasks are discovered structurally from this
// pack's own `tasks/<name>/task.mjs` by the repo's scheduler
// (packs/claudinite-tasks/discover.mjs), so none is declared here. Declared by hand in
// exactly one repo (this one, as "local/canon-curation"); that
// declaration cardinality is what makes its tasks central-once: a pack task
// runs per DECLARING repo, so one declaring repo means one unit per night, with
// no bespoke orchestrator step. Un-declaring it freezes canon absorption
// without touching the members' side (claudinite-growth).
export default {
  ruleRoutingGuidance: {
    belongs: 'fleet-facing curation of the shared corpus — promoting member lessons into packs/, sweeping the fleet stack, policing packs/',
    excludes: 'working rules for developing Claudinite itself — that is the claudinite local pack; a member tidying itself — tidy-repo',
  },
  // Packs-tree segregation is barrier DATA, never code this pack runs:
  // pack-independence is a declared check — a forbidReferences entry in this
  // pack's declared-checks.json, run by the engine's reference-scanning (the
  // same shape basics uses for claudinite-isolation). Its `allow` list IS the
  // engine surface — the one always-vendored engine/ root; a new surface root
  // would join it there, loudly (the barrier fails closed, never widens).
  requires: ['barriers'],
  // The prose-narration rule polices pack prose CONTENT (not segregation), so
  // it stays a code check, bundled here.
  // Delivery, not content: a pack's directory ships on its version number, so
  // whether THIS change moved it is a question only the diff can answer.
  // writing-claudinite-skills is canon-home activity (authoring corpus skills), so
  // this pack bundles it under its own skills/ — members author no corpus skills.
};

[
  {
    "id": "pack-independence",
    "severity": "blocking",
    "failureMessage": "the vendor set ships a pack only when declared, so a cross-pack import crashes every consumer that vendors one pack without the other",
    "fix": "declare the dependency (requires) and pass configuration, move the shared helper into engine/checks/helpers, or accept the import with a reason in .claudinite-settings.json",
    "relevantWhen": { "pathExists": "packs" },
    "forbidReferences": [
      {
        "siblings": "packs",
        "to": "*",
        "scope": "imports",
        "allow": ["engine", "packs/claudinite-tasks/shared-code"],
        "reason": "a pack imports only its own files, the engine surface, and the tasks pack's published shared-code/ — abilities otherwise cross pack boundaries through declaration and configuration, never imports; a pack's updates/ is carved out because no vendor set carries it, so an import there cannot crash a consumer (#1317)",
    "except": ["packs/claudinite-lifecycle/updates"]
      }
    ]
  }
]

