import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { parseVersion, compareVersions, versionFromLiteral } from '../../../../home/user/Claudinite/engine/version.mjs';

const REPO = '/home/user/Claudinite';
const ROW_RE = /^\|\s*(\d+(?:\.\d+)?)\s*\|/;
const SEP_RE = /^\|[\s:-]+\|/;

const files = execFileSync('git', ['ls-files', 'packs/*/VERSIONS.md'], { cwd: REPO, encoding: 'utf8' })
  .split('\n').filter(Boolean);

for (const rel of files) {
  const path = `${REPO}/${rel}`;
  const text = readFileSync(path, 'utf8');
  const lines = text.split('\n');

  const sepIdx = lines.findIndex((l) => SEP_RE.test(l.trim()));
  if (sepIdx === -1) continue;

  let end = sepIdx + 1;
  while (end < lines.length && ROW_RE.test(lines[end].trim())) end += 1;

  const bodyLines = lines.slice(sepIdx + 1, end);
  if (bodyLines.length < 2) continue;

  const decorated = bodyLines.map((line, i) => {
    const m = ROW_RE.exec(line.trim());
    return { line, i, version: m ? versionFromLiteral(m[1]) : null };
  });

  const alreadySorted = decorated.every((d, i) => i === 0
    || !parseVersion(d.version) || !parseVersion(decorated[i - 1].version)
    || compareVersions(d.version, decorated[i - 1].version) <= 0);
  if (alreadySorted) continue;

  const sorted = [...decorated].sort((a, b) => {
    if (!parseVersion(a.version) || !parseVersion(b.version)) return a.i - b.i;
    const cmp = compareVersions(b.version, a.version);
    return cmp !== 0 ? cmp : a.i - b.i;
  });

  const newLines = [...lines.slice(0, sepIdx + 1), ...sorted.map((d) => d.line), ...lines.slice(end)];
  writeFileSync(path, newLines.join('\n'));
  console.log(`sorted: ${rel}`);
}

